W = 2
I, R = "Inkoop", "Recht"

# ---------- Inkoop MC ----------
mc("ir2-i01", W, I, "Sourcing is een strategische keuze. Welke drie vragen beantwoord je daarmee?",
   ["Wat, hoeveel en wanneer kopen we in", "Waar, bij wie en onder welke voorwaarden kopen we in", "Wie beslist, wie betaalt en wie controleert", "Welke procedure, welke drempel en welke termijn"], 1,
   "Sourcing gaat over waar je inkoopt, bij wie en onder welke voorwaarden. Procedures en drempels horen bij aanbesteden.")
mc("ir2-i02", W, I, "Welke methode noemen de slides om het belang van een product of dienst voor de eigen organisatie te bepalen als basis voor het sourcingbeleid?",
   ["Het lineaire inkoopproces", "De methode van Kraljic", "TCO", "De sourcingcyclus"], 1,
   "De Kraljic-matrix zet financieel belang af tegen toeleveringsrisico. Daarmee bepaal je welke leveranciersrelatie en sourcingstrategie bij een product past.")
mc("ir2-i03", W, I, "Een speciaal reinigingsmiddel voor de operatiekamers wordt door één fabrikant ter wereld gemaakt. Welke vorm van sourcing is dit?",
   ["Single sourcing", "Sole sourcing", "Dual sourcing", "Multiple sourcing"], 1,
   "Sole sourcing betekent dat de leverancier monopolist is: je hebt geen keus. Bij single sourcing kies je zelf bewust voor één leverancier terwijl er meer zijn.")
mc("ir2-i04", W, I, "Een gemeente koopt kantoorartikelen bij een groot aantal leveranciers en laat ze steeds op prijs concurreren. Welke sourcingstrategie is dit en bij welk type product past die volgens de slides?",
   ["Single sourcing, strategische producten", "Dual sourcing, knelpuntproducten", "Multiple sourcing, routineproducten", "Sole sourcing, hefboomproducten"], 2,
   "Multiple sourcing gebruikt een veelvoud aan leveranciers. De slide koppelt dat aan routineproducten (RP). Single sourcing hoort bij strategische producten (SP), dual sourcing zit ertussenin.")
mc("ir2-i05", W, I, "Een cateraar ontwikkelt samen met de FM-afdeling een nieuw restaurantconcept en wordt verantwoordelijk voor dat deel van de dienstverlening. Welke samenwerkingsvorm is dit?",
   ["Co-makership", "Horizontale inkoopsamenwerking", "Offshore outsourcing", "Multiple sourcing"], 0,
   "Bij co-makership wordt de leverancier verantwoordelijk voor een deel van het eindproduct of de dienst. Het voorbeeld van het restaurantconcept staat letterlijk op de slide.")
mc("ir2-i06", W, I, "Een beveiligingsbedrijf denkt mee bij de herinrichting van een gebouw om veiligheidsrisico's te verkleinen. Hoe heet dit?",
   ["Co-development of co-design", "Turnkey outsourcing", "Verticale inkoopsamenwerking via een inkoopcombinatie", "Sole sourcing"], 0,
   "Bij co-development of co-design helpt de leverancier mee bij het ontwikkelen van een nieuw product of ontwerp.")
mc("ir2-i07", W, I, "Een aantal ziekenhuizen koopt samen in via Intrakoop. Wat voor samenwerking is dit?",
   ["Verticale samenwerking", "Horizontale samenwerking", "Co-makership", "Partial outsourcing"], 1,
   "Horizontale samenwerking is samenwerking tussen inkopers van organisaties die eigenlijk elkaars concurrenten of soortgenoten zijn. Intrakoop (zorg), VNG Realisatie (gemeenten) en Aedes (woningcorporaties) zijn de voorbeelden van de slides.")
mc("ir2-i08", W, I, "Wat is een risico van het streven naar een kleiner leveranciersbestand?",
   ["Hogere administratieve lasten", "Te grote afhankelijkheid van de leverancier", "Minder grip op de kwaliteit", "Meer transactiekosten"], 1,
   "De slides noemen: te grote afhankelijkheid, minder concurrentie op de leveranciersmarkt, aanvoerproblemen en te weinig productiecapaciteit. Een kleiner bestand verlaagt juist administratieve lasten en transactiekosten.")
mc("ir2-i09", W, I, "De schoonmakers van een extern bedrijf werken in jouw kantoorpand. Welke vorm van outsourcing is dat?",
   ["On-site", "Off-site", "Nearshore", "Offshore"], 0,
   "On-site: de uitbestede taak wordt door derden gedaan, maar op het terrein van de eigen organisatie.")
mc("ir2-i10", W, I, "Een gemeente laat haar archief digitaliseren door een bedrijf in Polen, binnen dezelfde tijdzone en op korte reisafstand. Welke vorm past het best?",
   ["On-site", "Nearshore", "Offshore naar een land ver weg", "Turnkey insourcing"], 1,
   "Nearshore is uitbesteden binnen een gebied dat goed bereikbaar is of in dezelfde of een naburige tijdzone ligt. Offshore is in het algemeen uitbesteden aan een organisatie in een ander land, vaak ver weg.")
mc("ir2-i11", W, I, "Welk argument hoort bij 'niet uitbesteden'?",
   ["Focus op kerntaken", "Specialistische kennis van de leverancier", "Verlies van regie en kennis", "Prestatiesturing op KPI's"], 2,
   "Tegen uitbesteden pleiten onder meer verlies van regie, afhankelijkheid, verlies van kennis, kwaliteitsrisico's, verborgen kosten en verlies van maatwerk. De andere drie zijn argumenten voor uitbesteden.")
mc("ir2-i12", W, I, "Wat is een voordeel van lokaal inkopen volgens de slides?",
   ["Altijd de laagste kostprijs", "Korte levertijden en minder problemen met cultuur, douane en financiële afwikkeling", "Toegang tot de beste producten wereldwijd", "Geen afhankelijkheid van leveranciers"], 1,
   "Lokaal inkopen geeft korte levertijden en minder problemen met cultuurverschillen, douane en betaling. Nadelen: je kunt naast de beste producten grijpen en elders zijn kostprijzen vaak lager.")

# ---------- Recht MC ----------
mc("ir2-r01", W, R, "Welke drie categorieën aanbestedingsplichtigen onderscheidt het boek?",
   ["Overheden, publiekrechtelijke instellingen en gesubsidieerde instellingen", "Overheden, ondernemers en consumenten", "Staat, provincies en gemeenten", "Overheden, aankoopcentrales en concessiehouders"], 0,
   "Categorie 1: overheden (art. 1.1 Aw). Categorie 2: publiekrechtelijke instellingen (art. 1.1 Aw). Categorie 3: gesubsidieerde instellingen (art. 2.8 Aw). Aankoopcentrales komen daarnaast aan bod.")
mc("ir2-r02", W, R, "Welke voorwaarden gelden cumulatief voor een publiekrechtelijke instelling?",
   ["Opgericht voor behoeften van algemeen belang (niet industrieel of commercieel), rechtspersoonlijkheid en een bepaalde mate van overheidsinvloed", "Meer dan 50% subsidie, een werk of dienst en boven de drempel", "Overheidstoezicht, 80% van de werkzaamheden voor de overheid en geen privaat kapitaal", "Een wettelijke taak, een eigen begroting en ambtenaren in dienst"], 0,
   "De drie cumulatieve voorwaarden staan in art. 1.1 Aw. De optie met 50% subsidie beschrijft de gesubsidieerde instelling, die met 80% en toezicht de quasi-inbesteding.")
mc("ir2-r03", W, R, "Waarom is zorgverzekeraar CZ volgens het oefenmateriaal geen publiekrechtelijke instelling?",
   ["Omdat CZ geen rechtspersoonlijkheid heeft", "Omdat CZ op commerciële beginselen werkt (rendement, doelmatigheid, rentabiliteit)", "Omdat CZ te weinig omzet heeft", "Omdat CZ in het buitenland gevestigd is"], 1,
   "CZ lijkt op een publiekrechtelijke instelling, maar werkt op commerciële beginselen. Daardoor voldoet CZ niet aan de eis 'anders dan van industriële of commerciële aard'.")
mc("ir2-r04", W, R, "Een private stichting krijgt 60% subsidie voor de verbouwing van haar gebouw (een werk). Wanneer is zij aanbestedingsplichtig op grond van art. 2.8 Aw?",
   ["Altijd, omdat ze subsidie krijgt", "Als de geraamde waarde van het werk boven de drempel voor werken ligt", "Nooit, want ze is een private partij", "Alleen bij leveringen boven de drempel"], 1,
   "Een gesubsidieerde instelling (meer dan 50% subsidie) moet aanbesteden voor werken en diensten boven de drempel. Leveringen vallen er niet onder, tenzij ze een ondergeschikt onderdeel van een werk of dienst zijn.")
mc("ir2-r05", W, R, "Wie is verantwoordelijk als een gesubsidieerde instelling de aanbestedingsregels niet naleeft?",
   ["De gesubsidieerde instelling alleen", "De subsidieverlenende overheid, die de subsidie aan naleving koppelt en kan intrekken", "De Europese Commissie", "De inschrijver die de opdracht krijgt"], 1,
   "Volgens de uitwerking bij oefenopdracht 2.3 is de subsidieverlener verantwoordelijk. Die stelt naleving als voorwaarde en kan de subsidie intrekken.")
mc("ir2-r06", W, R, "Wanneer is er sprake van een overheidsopdracht in de zin van art. 1.1 Aw?",
   ["Bij elke afspraak tussen overheid en burger", "Bij een schriftelijke overeenkomst onder bezwarende titel tussen ondernemer(s) en aanbestedende dienst(en) voor werken, leveringen of diensten", "Alleen bij een notariële akte", "Alleen als de overheid in geld betaalt"], 1,
   "De vier gemeenschappelijke kenmerken: schriftelijk (ruim uit te leggen, een e-mail is al genoeg), bezwarende titel, tussen ondernemer en aanbestedende dienst, en betrekking op werken, leveringen of diensten.")
mc("ir2-r07", W, R, "Een gemeente geeft een bedrijf geen geld, maar wel vrijstelling van leges in ruil voor een dienst. Is er een bezwarende titel?",
   ["Nee, er wordt niet betaald", "Ja, ook een op geld waardeerbaar voordeel zoals vrijstelling van leges of kwijtschelding van belasting telt", "Alleen als de vrijstelling boven de drempel ligt", "Nee, want leges zijn bestuursrecht"], 1,
   "Een bezwarende titel is alles wat op geld waardeerbaar is: een geldelijke vergoeding, kwijtschelding van belasting, vrijstelling van leges, enzovoort.")
mc("ir2-r08", W, R, "Een opdracht bestaat voor 60% uit de verbouwing van een pand en voor 40% uit het runnen van een evenementencentrum, en het doel is de dienstverlening. Hoe bepaal je het regime?",
   ["Puur op waarde, dus een werk", "Op het hoofdvoorwerp: wat is kenmerkend en wat is bijkomstig; hier een dienst", "Elk deel apart aanbesteden is altijd verplicht", "Bij twijfel geldt altijd het regime voor leveringen"], 1,
   "Bij werken gecombineerd met diensten of leveringen beslist het hoofdvoorwerp; de waarde is maar één criterium (Gestion Hotelera). Bij leveringen plus diensten beslist wel de waarde. Zie oefenopdracht 2.4.")
mc("ir2-r09", W, R, "Wat is het kenmerkende verschil tussen een concessie en een gewone overheidsopdracht?",
   ["Een concessie is altijd mondeling", "Bij een concessie bestaat de tegenprestatie uit het recht tot exploitatie en draagt de concessiehouder het exploitatierisico", "Een concessie geldt alleen voor leveringen", "Bij een concessie betaalt de overheid altijd meer"], 1,
   "Bij een concessie wordt de ondernemer betaald door de gebruikers (bijvoorbeeld tol of parkeergeld) en draagt hij zelf het exploitatierisico. Concessies voor leveringen bestaan niet.")
mc("ir2-r10", W, R, "Het ministerie laat een toltunnel bouwen en vult eventuele verliezen van de exploitant volledig aan. Welk deel van de Aanbestedingswet geldt?",
   ["Deel 2A, want er wordt tol geheven", "Deel 2, want zonder exploitatierisico is het geen concessie maar een gewone overheidsopdracht", "Geen enkel deel, want de overheid betaalt niet", "Deel 3, want het is een werk"], 1,
   "Omdat het ministerie de verliezen aanvult, draagt de bouwer geen exploitatierisico. Dan is het geen concessie maar een gewone opdracht voor een werk (Deel 2), zie oefenopdracht 2.6.")
mc("ir2-r11", W, R, "Een gemeente geeft een opdracht aan haar eigen BV zonder aanbesteding. Wat is GEEN voorwaarde voor quasi-inbesteding (art. 2.24a Aw)?",
   ["Toezicht zoals op de eigen diensten", "Meer dan 80% van de werkzaamheden voor de aanbestedende dienst", "Geen directe participatie van particulier kapitaal", "De BV moet goedkoper zijn dan de markt"], 3,
   "De drie voorwaarden zijn toezicht als op de eigen dienst, het 80%-criterium en geen privaat kapitaal. Goedkoper zijn dan de markt is geen voorwaarde.")
mc("ir2-r12", W, R, "Voor een levering van €1,2 miljoen wil een gemeente een perceel van €75.000 los en zonder Europese aanbesteding gunnen. Kan dat via de percelenregeling?",
   ["Nee, percelen moeten altijd Europees", "Ja, want het perceel is niet meer dan €80.000 en de vrijgestelde percelen samen zijn niet meer dan 20% van de totale waarde", "Alleen bij werken", "Ja, elk perceel onder de drempel mag vrij"], 1,
   "Bij leveringen en diensten mag een perceel van maximaal €80.000 zonder Europese aanbesteding, zolang de vrijgestelde percelen samen niet boven 20% van de totale waarde komen (art. 2.18 en 2.19 Aw). Voor werken is de grens €1.000.000. Daarbuiten geldt het splitsingsverbod.")

# ---------- Open vragen ----------
op("ir2-io1", W, I, "Een zorginstelling overweegt de schoonmaak uit te besteden. Geef drie argumenten voor en drie argumenten tegen uitbesteden die specifiek voor een zorginstelling gelden.",
   "Voor: specialistische kennis van infectiepreventie en reinigingsprotocollen; focus op de kerntaak zorg; flexibiliteit bij pieken zoals een uitbraak; prestatiesturing op KPI's; minder personele verantwoordelijkheid. Tegen: verlies van regie over hygiëne, die direct de patiëntveiligheid raakt; kwaliteitsrisico's en afhankelijkheid van de leverancier; minder binding van schoonmakers met de afdeling en de patiënten; verborgen kosten van contractmanagement; privacy op afdelingen.",
   ["Drie argumenten voor", "Drie argumenten tegen", "Argumenten toegepast op de zorgcontext (hygiëne, patiëntveiligheid, privacy)"])
op("ir2-io2", W, I, "Leg uit wat het verschil is tussen single, sole, dual en multiple sourcing en geef bij elk een facilitair voorbeeld.",
   "Single: bewust één leverancier terwijl er meer zijn, bijvoorbeeld één cateraar voor alle restaurants. Sole: de leverancier is monopolist, bijvoorbeeld een speciaal reinigingsmiddel van één fabrikant. Dual: afspraken met twee leveranciers om afhankelijkheid te beperken, bijvoorbeeld twee uitzendbureaus voor schoonmaakpersoneel. Multiple: veel leveranciers, bijvoorbeeld kantoorartikelen of losse onderhoudsklussen.",
   ["Single en sole juist onderscheiden (eigen keuze tegenover monopolie)", "Dual en multiple juist uitgelegd", "Bij elke vorm een passend facilitair voorbeeld"])
op("ir2-io3", W, I, "Wat is het verschil tussen horizontale en verticale inkoopsamenwerking? Geef van beide een voorbeeld en noem een voordeel.",
   "Horizontaal: samenwerking tussen inkopers van organisaties die soortgenoten of concurrenten zijn, zoals ziekenhuizen via Intrakoop of gemeenten via VNG Realisatie. Voordeel: bundeling van volume, dus betere prijzen en minder proceskosten, en gedeelde kennis. Verticaal: samenwerking tussen schakels in de keten, dus tussen inkopende organisatie en leverancier, zoals co-makership met een cateraar. Voordeel: innovatie, betere afstemming en ketenvoordeel.",
   ["Horizontaal juist uitgelegd met voorbeeld", "Verticaal juist uitgelegd met voorbeeld", "Bij beide een passend voordeel"])
op("ir2-ro1", W, R, "Is de HAN aanbestedingsplichtig? Werk je antwoord uit met de juiste categorie, de voorwaarden en het artikel.",
   "Ja. De HAN is een publiekrechtelijke instelling (categorie 2, art. 1.1 Aw). Ze is opgericht om te voorzien in een behoefte van algemeen belang die niet industrieel of commercieel van aard is, namelijk onderwijs. Ze heeft rechtspersoonlijkheid als stichting (art. 2:3 BW). En er is overheidsinvloed, omdat ze in hoofdzaak door de overheid wordt gefinancierd. De drie voorwaarden zijn cumulatief vervuld.",
   ["Juiste categorie (publiekrechtelijke instelling) en art. 1.1 Aw", "Alle drie de voorwaarden genoemd", "Toegepast op de HAN (onderwijs, stichting, overheidsfinanciering)"])
op("ir2-ro2", W, R, "Leg uit wat een raamovereenkomst is, hoe lang die maximaal mag duren en met hoeveel partijen je hem kunt sluiten. Noem de artikelen.",
   "Een raamovereenkomst is een overeenkomst tussen een of meer aanbestedende diensten en een of meer ondernemers. Het doel is voor een bepaalde periode de voorwaarden vast te leggen voor opdrachten die later worden gegund, bijvoorbeeld de prijs of de beoogde hoeveelheid (art. 2.44 Aw). De looptijd is maximaal 4 jaar (art. 2.140 Aw; de slide noemt lid 3, de oefentoets lid 2, dus check je bundel). Je kunt hem met één of meer partijen sluiten (art. 2.143 lid 1 Aw).",
   ["Definitie raamovereenkomst", "Maximaal 4 jaar met art. 2.140", "Met een of meer partijen (art. 2.143)"])
op("ir2-ro3", W, R, "Noem vier soorten uitzonderingen in de Aanbestedingswet waardoor een overheidsopdracht niet Europees hoeft te worden aanbesteed, met artikel, en leg uit waarom uitzonderingen strikt worden uitgelegd.",
   "Bijvoorbeeld: echte defensieopdrachten en geheime opdrachten (art. 2.23 Aw, art. 346 VWEU); opdrachten over onroerende zaken, arbitrage en bemiddeling, onderzoek of arbeidsovereenkomsten (art. 2.24 Aw); quasi-inbesteding (art. 2.24a Aw); publiek-publieke samenwerking (art. 2.24b en 2.24c Aw); de percelenregeling (art. 2.18 en 2.19 Aw). Uitzonderingen worden strikt toegepast omdat ze afwijken van de hoofdregel van mededinging. Wie zich op een uitzondering beroept, moet bewijzen dat die van toepassing is.",
   ["Vier juiste uitzonderingen", "Met juiste artikelen", "Uitleg strikte uitleg en bewijslast"])

# ---------- Casussen ----------
cs("ir2-ic1", W, I, "Uitbesteden in het Rijnstate-ziekenhuis",
   "Een ziekenhuis met 4.000 medewerkers op drie locaties overweegt de volgende activiteiten uit te besteden:\n- de patiëntenmaaltijden;\n- de schoonmaak van de operatiekamers;\n- het wassen van linnen en beddengoed;\n- de ICT-servicedesk voor medewerkers;\n- de receptie bij de hoofdingang.\nDe raad van bestuur wil kosten besparen, maar is bang de regie te verliezen.",
   [("Bepaal voor drie van de activiteiten welke vorm van outsourcing (on-site, off-site, nearshore of offshore) het meest passend is en onderbouw je keuze.",
     "Bijvoorbeeld: schoonmaak operatiekamers on-site, het moet op de locatie gebeuren. Linnen wassen off-site in een externe wasserij. Patiëntenmaaltijden on-site (regenereren op de afdeling) of off-site (centrale productiekeuken). ICT-servicedesk off-site of nearshore, het kan op afstand, maar let op privacy van patiëntgegevens. Receptie on-site.",
     ["Drie activiteiten met een passende vorm", "Elke keuze onderbouwd met de aard van de activiteit"]),
    ("Welke activiteit zou je niet uitbesteden of met extra waarborgen? Waarom?",
     "Een goed antwoord kiest bijvoorbeeld de schoonmaak van de operatiekamers. Infectiepreventie raakt direct de patiëntveiligheid, dus verlies van regie of kwaliteit is hier het grootst. Uitbesteden kan alleen met strakke eisen, audits en KPI's. Een ander verdedigbaar antwoord is de ICT-servicedesk vanwege privacy.",
     ["Duidelijke keuze", "Onderbouwing met risico (patiëntveiligheid, privacy, kerntaak)"]),
    ("Noem de drie grootste risico's van uitbesteden voor dit ziekenhuis en een maatregel per risico.",
     "Verlies van regie: KPI's en een SLA met periodieke rapportage. Afhankelijkheid van de leverancier: exit-afspraken en kennis in huis houden (regieorganisatie). Kwaliteitsrisico's: audits, steekproeven en malussen. Ook verdedigbaar: verborgen kosten, privacy en minder binding van personeel.",
     ["Drie relevante risico's", "Bij elk risico een passende maatregel"])])
cs("ir2-ic2", W, I, "Sourcingbeleid voor een hogeschool",
   "Je stelt het sourcingbeleid op voor een hogeschool met 30.000 studenten. Je kijkt naar vier categorieën:\n1. kantoorartikelen;\n2. onderhoud van de brandmeldinstallaties (wettelijk verplicht, weinig gespecialiseerde aanbieders in de regio);\n3. catering voor alle locaties (grote uitgave, veel aanbieders);\n4. een speciaal reinigingsmiddel voor de laboratoria dat maar één fabrikant maakt.",
   [("Plaats elke categorie in een kwadrant van de Kraljic-matrix en licht kort toe.",
     "Gangbare indeling: kantoorartikelen zijn een routineproduct (laag financieel belang, laag risico). Brandmeldinstallaties zijn een knelpuntproduct (beperkt financieel belang, maar hoog risico: wettelijk verplicht, weinig aanbieders). Catering is een hefboomproduct (hoog financieel belang, veel aanbieders), al kun je het ook strategisch noemen vanwege de impact op studenten. Het reinigingsmiddel is een knelpuntproduct (laag bedrag, hoog leveringsrisico).",
     ["Kwadranten juist voor minstens drie categorieën", "Toelichting met financieel belang en toeleveringsrisico"]),
    ("Kies per categorie een passende sourcingstrategie (single, sole, dual of multiple) en onderbouw.",
     "Kantoorartikelen: multiple sourcing of één raamcontract via concurrentie, de markt is ruim. Brandmeldinstallaties: dual sourcing om afhankelijkheid te beperken, of single met goede afspraken. Catering: single sourcing per locatie of dual voor concurrentiedruk. Reinigingsmiddel: sole sourcing, er is maar één fabrikant; zorg voor veiligheidsvoorraad.",
     ["Passende strategie per categorie", "Onderbouwing gekoppeld aan risico en markt"]),
    ("Welk risico loopt de hogeschool als ze haar leveranciersbestand sterk inkrimpt? Noem er twee.",
     "Te grote afhankelijkheid van de overgebleven leveranciers, minder concurrentie op de leveranciersmarkt, aanvoerproblemen als een leverancier uitvalt en te weinig capaciteit.",
     ["Twee juiste risico's uit de slides"])])
cs("ir2-rc1", W, R, "Afvalinzameling van vier gemeenten",
   "De gemeenten Ede, Wageningen, Renkum en Barneveld richten samen de rechtspersoon AfvalVallei BV op. Elke gemeente heeft 25% van de aandelen. Ze willen de afvalinzameling (waarde ruim €10 miljoen) zonder aanbesteding aan AfvalVallei gunnen. AfvalVallei doet 90% van haar werk voor de vier gemeenten en 10% voor bedrijven in de regio.\nEen commerciële afvalverwerker die al jaren voor Ede werkt, vindt dit oneerlijk.",
   [("Zijn de gemeenten aanbestedingsplichtig? Welke categorie en welk artikel?",
     "Ja. Gemeenten zijn territoriale lichamen en vallen onder de overheden, categorie 1 (art. 1.1 Aw).",
     ["Ja, overheid/territoriaal lichaam, art. 1.1 Aw"]),
    ("Mogen de gemeenten de opdracht zonder aanbesteding aan AfvalVallei gunnen? Toets aan de juiste uitzondering.",
     "Mogelijk wel, via publiek-publieke samenwerking met een rechtspersoon (art. 2.24b Aw). Voorwaarden: gezamenlijk toezicht zoals op de eigen diensten (de vier gemeenten samen hebben 100% en sturen de BV), meer dan 80% van de werkzaamheden voor de toezichthoudende diensten (90%, dus voldaan) en geen participatie van particulier kapitaal (alleen gemeenten zijn aandeelhouder). Als alles klopt, hoeft niet te worden aanbesteed. Uitzonderingen worden wel strikt uitgelegd.",
     ["Juiste uitzondering: art. 2.24b (of quasi-inbesteding 2.24a met uitleg gezamenlijk)", "De drie voorwaarden genoemd", "Toegepast op de feiten (100% publiek, 90%)"]),
    ("Wat verandert er als de commerciële afvalverwerker 20% van de aandelen krijgt, of als AfvalVallei 30% van haar werk voor bedrijven gaat doen?",
     "Met 20% privaat kapitaal is niet meer voldaan aan de voorwaarde 'geen participatie van particulier kapitaal', dus moet worden aanbesteed. Bij 30% werk voor derden komt de BV onder de 80%-grens (70% voor de gemeenten), dus vervalt de uitzondering ook. In beide gevallen moet de opdracht Europees worden aanbesteed.",
     ["Privaat kapitaal: uitzondering vervalt", "Onder 80%: uitzondering vervalt", "Conclusie: Europees aanbesteden"])])
